// Layer 4, test helper. What the website's three files are built from in the test of G139
// (tests/data/hubs/website-files.test.ts): the lines of the hub's settings file, the CV those lines
// write, the manifests and the career file a copy of the demo hub is given, and the website's own
// file. It holds the rows' inputs apart from the rows, which read them.

import { parse } from 'yaml';
import type { CvSection, CvWords } from '../../../src/lib/data/sources/config/settings/files.ts';

